<?php
/**
 * Self-contained import: 51 performers + 50 leads
 * Deletes all existing performers first. Keeps Superadmin.
 * Default password: Temp4Pass (hashed with bcrypt)
 * Run: php import_all.php
 */

// DB config
$host='localhost'; $db='luxe_talent'; $user='Ezmator7700'; $pass='Sonia@7700';
$pdo = new PDO("mysql:host=$host;dbname=$db;charset=utf8mb4", $user, $pass, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);

// Embedded data
$REG_DATA = '';
$LEADS_DATA = '';

$performers = json_decode(gzuncompress(base64_decode($REG_DATA)), true);
$leads = json_decode(gzuncompress(base64_decode($LEADS_DATA)), true);

echo "=== IMPORTING " . count($performers) . " PERFORMERS + " . count($leads) . " LEADS ===\n\n";

// 1. Delete all existing performers
echo "Deleting existing performers...\n";
$del = $pdo->prepare("DELETE FROM registration WHERE role='performer'");
$del->execute();
echo "Deleted " . $del->rowCount() . " performers\n";
$pdo->exec("DELETE FROM schedule WHERE email NOT IN (SELECT email FROM registration)");
echo "Cleaned orphan schedules\n\n";

// 2. Import performers
$added = 0; $errors = 0;
$dbCols = ['email','password_hash','role','first_name','last_name','stage_name','alternate_user_names',
    'recruiter_name','applying_for','status','phone','street_address','city','state','zip_code','country',
    'date_of_birth','display_age','primary_language','other_language','about_me','what_turns_you_on',
    'what_turns_you_off','height','weight','build','ethnicity','eyes_color','hair_color','hair_length',
    'breast_size','butt_size','pubic_hair','dress_size','orientation','sexual_preferences','interested_in',
    'platform','studio_fee','profile_photo','id_front','id_back','consent','signed_at'];

$placeholders = implode(',', array_fill(0, count($dbCols), '?'));
$sql = 'INSERT INTO registration (' . implode(',', $dbCols) . ') VALUES (' . $placeholders . ')';
$stmt = $pdo->prepare($sql);

foreach ($performers as $p) {
    $pw = $p['password'] ?: 'Temp4Pass';
    
    // Fix date
    $dob = null;
    if (!empty($p['date_of_birth'])) {
        $ts = strtotime($p['date_of_birth']);
        if ($ts) $dob = date('Y-m-d', $ts);
    }
    
    $dispAge = !empty($p['display_age']) ? (int)$p['display_age'] : null;
    if ($dispAge === 0) $dispAge = null;
    
    try {
        $stmt->execute([
            $p['email'], password_hash($pw, PASSWORD_BCRYPT), 'performer',
            $p['first_name'], $p['last_name'], $p['stage_name'], $p['alternate_usernames'],
            $p['recruiter_name'], $p['applying_for'], $p['status'] ?: 'pending',
            $p['phone'], $p['street_address']?:'TBD', $p['city']?:'TBD', $p['state']?:'TBD',
            $p['zip_code']?:'00000', $p['country']?:'US',
            $dob, $dispAge, $p['primary_language']?:'English', $p['other_language'],
            $p['about_me'], $p['turns_on'], $p['turns_off'],
            $p['height'], $p['weight'], $p['build'], $p['ethnicity'],
            $p['eye_color'], $p['hair_color'], $p['hair_length'],
            $p['breast_size'], $p['butt_size'], $p['pubic_hair'], $p['dress_size'],
            $p['orientation'], $p['sexual_preferences'], $p['interested_in'],
            $p['platform'], $p['studio_fee'],
            $p['profile_photo'], $p['id_front'], $p['id_back'],
            1, date('Y-m-d H:i:s')
        ]);
        $added++;
        echo "Added: " . $p['email'] . " (" . ($p['stage_name']?:'no stage') . ")\n";
    } catch (Throwable $e) {
        echo "ERROR " . $p['email'] . ": " . $e->getMessage() . "\n";
        $errors++;
    }
}
echo "\nPerformers: $added added, $errors errors\n\n";

// 3. Delete existing leads and import
echo "Deleting existing leads...\n";
$pdo->exec("DELETE FROM leads");
$lAdded = 0;
$lStmt = $pdo->prepare('INSERT INTO leads (stage_name,full_name,email,phone,instagram,country,recruiter,result,notes) VALUES (?,?,?,?,?,?,?,?,?)');
foreach ($leads as $l) {
    try {
        $lStmt->execute([$l['stage_name'],$l['full_name'],$l['email'],$l['phone'],$l['instagram'],$l['country'],$l['recruiter'],$l['result'],$l['notes']]);
        $lAdded++;
    } catch (Throwable $e) {
        echo "Lead ERROR: " . $e->getMessage() . "\n";
    }
}
echo "Leads: $lAdded added\n\n";

echo "=== DONE ===\n";
echo "Performers: $added | Leads: $lAdded\n";
echo "Default password: Temp4Pass (bcrypt hashed)\n";
